import{_ as o,o as t,c as a,al as r}from"./chunks/framework.y_Bi8mTF.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"page"},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),i={name:"privacy-policy.md"};function n(s,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="esa-privacy-notice-for-eopf-sentinel-zarr-explorer" tabindex="-1">ESA Privacy Notice for EOPF Sentinel Zarr Explorer <a class="header-anchor link" href="#esa-privacy-notice-for-eopf-sentinel-zarr-explorer" aria-label="Permalink to &quot;ESA Privacy Notice for EOPF Sentinel Zarr Explorer&quot;">​</a></h2><p>The European Space Agency (hereafter &quot;the <strong>Agency</strong>&quot; or <strong>&quot;ESA&quot;</strong> or <strong>&quot;We&quot;</strong>) is committed to protecting Personal Data in line with the ESA Framework on Personal Data Protection (herein the <strong>&quot;ESA PDP Framework&quot;</strong>) available at: <a href="http://www.esa.int/About_Us/Law_at_ESA/Highlights_of_ESA_rules_and_regulations" class="link" target="_blank" rel="noreferrer">http://www.esa.int/About_Us/Law_at_ESA/Highlights_of_ESA_rules_and_regulations</a></p><p>composed of:</p><ul><li>the Principles of Personal Data Protection adopted by the ESA Council on 13 June 2017</li><li>the Rules of Procedure for the Data Protection Supervisory Authority adopted by ESA Council on 13 June 2017</li><li>the Policy on Personal Data Protection (including its Annex entitled &quot;Governance Scheme of the ESA&#39;s Personal Data Protection&quot;) adopted by the Director General of ESA on 1 March 2022 (&quot;<strong>ESA PDP Policy</strong>&quot;).</li></ul><p>This notice is intended to describe why and how Your personal data are collected and processed by or on behalf of ESA as Data Controller, on the initiative of the ESA above-mentioned Department, as well as what rights You have in relation to Your personal data. It also informs You about the contact details of the Data Protection Officer. This privacy notice was last updated on 24/06/2026. It must be read in conjunction with the ESA PDP Framework and other privacy notices referred to herein.</p><h4 id="how-can-you-contact-esa-regarding-this-notice" tabindex="-1">How can you contact ESA regarding this notice? <a class="header-anchor link" href="#how-can-you-contact-esa-regarding-this-notice" aria-label="Permalink to &quot;How can you contact ESA regarding this notice?&quot;">​</a></h4><p>The ESA Data Protection Officer (&quot;DPO&quot;) may be contacted in line with the ESA PDP Framework at <a href="mailto:DPO@esa.int" class="link" target="_blank" rel="noreferrer">DPO@esa.int</a>. Specific information is available upon request from the DPO.</p><h4 id="what-kinds-of-personal-data-are-collected-and-further-processed" tabindex="-1">What kinds of personal data are collected and further processed? <a class="header-anchor link" href="#what-kinds-of-personal-data-are-collected-and-further-processed" aria-label="Permalink to &quot;What kinds of personal data are collected and further processed?&quot;">​</a></h4><p>We collect and process various kinds of personal data and may require You to provide personal data for the purposes mentioned later in this notice. Depending on the purpose for which they are collected and further processed, the personal data may include the following:</p><ul><li><p>Data that Your browser transmits to our website server (i.e. log files) without actively providing us with information about You, as well as data that we collect via the use of cookies and similar technologies.</p></li><li><p><strong>Identity Data</strong>: including Your names, surname, email address, or other identity information, such as unique user identifier when using the CDSE identity for authentication.</p></li></ul><p><strong>Log files</strong></p><p>Our log files contain the following information: (i) date and time of retrieval of our website, (ii) type, version and settings of your web-browser, (iii) your operating system and internet service provider, (iv) requested pages and files, (v) website used prior to visiting our website as well as (vi) your IP-address. The IP address is a specific number assigned to your computer which enables your device to communicate in a network using the Internet Protocol (IP). IP addresses may qualify as personal data as they technically allow the identification of the user in certain circumstances.</p><p><strong>Other personal information You may disclose via social media or in the use thereof</strong></p><p>Other personal data that You have to the extent you made them public, such as:</p><ul><li>Your messages, date, and time the message was sent.</li><li>the content of the questions you have asked.</li><li>other data mentioned in Your messages.</li><li>data You have made public.</li></ul><h4 id="how-are-your-personal-data-collected-or-further-processed" tabindex="-1">How are Your personal data collected or further processed? <a class="header-anchor link" href="#how-are-your-personal-data-collected-or-further-processed" aria-label="Permalink to &quot;How are Your personal data collected or further processed?&quot;">​</a></h4><p>In addition to the personal data, We collect directly from You other pieces of information (e.g. you fill in a form submitted by, or for, ESA).</p><p>We collect personal data both automatically when you interact with our website and when you actively provide it to us.</p><p><strong>Registration</strong></p><p>Your personal data is collected when you authenticate to access the EOPF Sentinel Zarr Explorer website (explorer.eopf.copernicus.eu) and its subdomains. We utilise the Copernicus Data Space Ecosystem (CDSE) OAuth service for user authentication and access management. Consequently, we do not directly collect, manage, or store your account passwords. When you log in via CDSE OAuth, we collect and process the identity information securely transmitted to us by the CDSE identity provider (which typically includes your name, email address, and a unique user identifier). This data collection is strictly necessary to verify your identity, establish your user session, and manage your access rights within the openEO Studio studio.explorer.eopf.copernicus.eu. This information is processed for as long as you maintain an active session or account relationship with the platform and is deleted when no longer necessary for these purposes.</p><p><strong>Log Files</strong></p><p>The processing of these log files is necessary for us to maintain the functionality, stability, and security of our website. We may also process them for the purpose of forensic investigations in the case of a security incident or to generate user traffic statistics.</p><p>Legal basis: Article 5.2.1.i (a) and (d) of the ESA Policy on Personal Data Protection -- processing is necessary for the performance of an activity carried out by the Agency within its purpose and for security.</p><p><strong>Cookies</strong></p><p>This website uses cookies. For full details on the types of cookies used, their purpose, and how to manage your preferences, please refer to our <a href="/pr-preview/pr-111/cookie-settings" class="link">Cookie Notice</a>.</p><h4 id="why-do-we-collect-and-further-process-your-personal-data" tabindex="-1">Why do we collect and further process your personal data? <a class="header-anchor link" href="#why-do-we-collect-and-further-process-your-personal-data" aria-label="Permalink to &quot;Why do we collect and further process your personal data?&quot;">​</a></h4><p>We collect and process Your personal data necessary for the activities conducted to fulfil Our purpose, which is &quot;<em>to provide for and to promote, for exclusively peaceful purposes, cooperation among European States in space research and technology and their space applications, with a view to their being used for scientific purposes and for operational space applications systems</em>&quot; (as per ESA Convention). We serve the public interest, and we wish to foster the public interest in space activities and programmes.</p><p>All the processing carried out by, or on behalf of, ESA falls in this general purpose and, in particular, into one of the reasons permitted under ESA PDP Framework, in particular under ESA PDP Policy.</p><p>In any case, we do not process your personal data for activities where our interests are overridden by the impact on you, unless we have your consent or are otherwise required or legally permitted.</p><p>Your personal data are collected and further processed for the following purposes:</p><ul><li>To provide you access to the ESA Copernicus Earth Observation Processing Framework (EOPF) Sentinel Zarr Explorer</li><li>To manage your relationship with The Agency as well as your feedback for improvement of the website</li></ul><p>In addition to these purposes, the Agency may use your personal information for any of the purposes mentioned in Article 5 of the Policy on Personal Data Protection.</p><p><strong>Opt-out</strong></p><p>Users can delete their accounts from the restricted section at any time. An email must be sent to <a href="mailto:jonas@developmentseed.org" class="link" target="_blank" rel="noreferrer">jonas@developmentseed.org</a>, asking for the removal of the account. Once the removal is effective, users will no longer be able to access the restricted section, and their data will be permanently deleted from the server. Additionally, users have the right to revoke their consent at any time to use their personal data for one or more of the above-mentioned processing purposes.</p><h4 id="on-what-legal-grounds-do-we-collect-and-process-your-data" tabindex="-1">On what legal grounds do We collect and process Your data? <a class="header-anchor link" href="#on-what-legal-grounds-do-we-collect-and-process-your-data" aria-label="Permalink to &quot;On what legal grounds do We collect and process Your data?&quot;">​</a></h4><p>We process Your personal data pursuant to the ESA PDP Framework, in particular pursuant to Article 5 of the ESA PDP Policy, for fair, specified and legitimate purposes or for purposes compatible therewith. Other ESA Rules and Regulations may serve as legal basis, as they may be indicated to You in additional notices, as appropriate.</p><p><strong>5.1 General basis for processing under ESA PDP Policy</strong></p><p>Generally, the processing referred to in this notice falls under <strong>Article 5.2.1 of the ESA PDP Policy</strong>, i.e.:</p><p>a. for the performance of an activity carried out by ESA within its purpose and in the framework of, and in conformity with, the ESA Convention, the Policy on Personal Data Protection adopted by Director General of ESA on 1 March 2022, and the applicable rules and procedures, including ESA Security Regulations and Directives; this includes Processing necessary for ESA&#39;s management and functioning, Dispute Resolution Procedure, and or Investigation Procedures; or b. for compliance with a legal obligation to which ESA is subject; or c. for tasks in the frame of ESA&#39;s cooperation with the competent authority of Member States, in order to facilitate the proper administration of justice; or d. for security; or e. for the performance of a contract concluded by ESA within its purpose in relation with an activity carried out by ESA in the framework of, and in conformity with, the ESA Convention and the applicable rules and procedures; or f. for Your legitimate interest; or g. for purposes covered by Your Consent, as it may be obtained from You as mentioned herein or under a separate document (e.g. Consent form).</p><p><strong>5.2 Consent</strong></p><p>When consent is the most appropriate lawful basis for processing, it will be requested from You and You can refuse to consent. Depending on the situation, Your consent may be given by various modalities (e.g. written form, verbally) and may in particular result from:</p><p>(i) filling in paper consent forms, responding to questionnaires, (ii) use of electronic means, such as mouse-click, swipe, keystroke, (iii) use of a service-specific user interface (for example, via a website, an app, a log-on account, the interface of an IoT device or by e-mail), choosing certain settings in connection thereof, (iv) filling in electronic consent forms, using digital signatures, sending email(s), sending SMS, filling in web forms for newsletter subscriptions, filling in event registration forms, responding to surveys, filling in and submitting applications, (v) positive behaviour or action, based on the knowledge of the fact that such behaviour or action involves agreement, such as:</p><ul><li>You enter into an area covered by a privacy notice on video recording;</li><li>You drop your business card in an area dedicated to collecting information for the purposes indicated in that area;</li><li>You publicly express opinions, make statements, create posts, share declarations, aware of the fact that each of them may trigger responses in connection with the subject matter covered by such opinions, statements, posts, declarations;</li><li>You send Your name and address to us to obtain information from us.</li></ul><p>When you consented to specific processing, you may withdraw the consent or exercise your rights in line with Article 9 herein. Unless otherwise advised in a separate notice or by ESA DPO, you can withdraw consent by contacting <a href="mailto:DPO@esa.int" class="link" target="_blank" rel="noreferrer">DPO@esa.int</a>.</p><p><em>For example: In case you provided your consent to subscribe to an activity, we may process all the data on your interests to build a profile of the topics you are interested in.</em> If you unsubscribe, we delete retrievable personal data relating to or collected in the context of the activity from our systems and services, including the profile(s) relating to you, where ESA is Controller.</p><p>If Your data was processed for several purposes, We will not process personal data for the purposes for which consent has been withdrawn.</p><h4 id="in-which-circumstances-may-we-transfer-or-provide-access-to-your-personal-data" tabindex="-1">In which circumstances may We transfer or provide access to Your personal data? <a class="header-anchor link" href="#in-which-circumstances-may-we-transfer-or-provide-access-to-your-personal-data" aria-label="Permalink to &quot;In which circumstances may We transfer or provide access to Your personal data?&quot;">​</a></h4><p>No personal data provided in the frame of this activity will be further distributed.</p><h4 id="how-long-do-we-retain-your-personal-data-for" tabindex="-1">How long do We retain Your personal data for? <a class="header-anchor link" href="#how-long-do-we-retain-your-personal-data-for" aria-label="Permalink to &quot;How long do We retain Your personal data for?&quot;">​</a></h4><p>Your data is stored for the shortest time possible, considering the reasons why we need to process Your data, as well as all legal obligations applicable to ESA. The ESA established time limits to erase or review the data stored. Retention periods applied by the ESA are proportionate to the purposes for which they were collected. Thus, ESA will keep Your personal data for as long as necessary for the fulfilment of those purposes, which will be at least for the duration of the EOPF Sentinel Zarr Explorer Contract (i.e. until December 2026), and shall be deleted afterwards. By way of exception, We may keep Your personal data for a longer period, for archiving purposes in the public interest or for reasons of scientific or historical research, being reminded that appropriate technical and organisational measures are in place (e.g. anonymisation, encryption, etc.).</p><h4 id="how-do-we-protect-and-safeguard-your-personal-data" tabindex="-1">How do We protect and safeguard Your personal data? <a class="header-anchor link" href="#how-do-we-protect-and-safeguard-your-personal-data" aria-label="Permalink to &quot;How do We protect and safeguard Your personal data?&quot;">​</a></h4><p>All processing operations are carried out pursuant to ESA Rules and Regulations, including ESA PDP Framework and ESA Security Regulations. In particular, the ESA collects and processes personal data in conditions protecting confidentiality, integrity and security of personal data.</p><p>In order to protect Your personal data, ESA has implemented a number of technical and organisational measures against the risks of loss as well as against unauthorised access, destruction, use, modification or disclosure of personal data, in particular when such risks concern sensitive personal data.</p><p>These measures consider the state of the art, the costs of implementation and the nature, scope, context and purposes of processing as well as the risk of varying likelihood and severity for the rights and freedoms of natural persons. They may include, as appropriate, the pseudonymisation and encryption of personal data.</p><h4 id="what-are-your-rights-as-data-subject-and-how-can-you-exercise-them" tabindex="-1">What are Your rights as data subject and how can you exercise them? <a class="header-anchor link" href="#what-are-your-rights-as-data-subject-and-how-can-you-exercise-them" aria-label="Permalink to &quot;What are Your rights as data subject and how can you exercise them?&quot;">​</a></h4><p>Under conditions detailed in the ESA Personal Data Protection Framework, You have:</p><ul><li>the right to be informed about the identity of the data controller, the contact details of the data protection officer, the purpose of the data processing, the data recipients to whom the personal data shall be disclosed, the rights of rectification or erasure of his/her data, the storage time-limits (if any), the practical modalities of exercising the rights, etc.; this is the purpose of this privacy notice and any other notice referred to herein;</li><li>the right to access the personal data We process about You; unless you have access to such data via an account, You may send us Your request by email to <a href="mailto:dpo@esa.int" class="link" target="_blank" rel="noreferrer">dpo@esa.int</a>;</li><li>the right to have Your personal data erased, rectified, completed; if You want to review and correct the personal information, You can either do it yourself, in case You have access to such data via an account, or You may send us Your request by email to <a href="mailto:dpo@esa.int" class="link" target="_blank" rel="noreferrer">dpo@esa.int</a>;</li><li>the right to lodge a complaint before the Supervisory authority, in accordance with the latter&#39;s rules of procedure. In case You demonstrate, or have serious reasons to believe, that a data protection incident occurred in relation with Your personal data, following a decision of ESA, You may notify us thereof by email to <a href="mailto:dpo@esa.int" class="link" target="_blank" rel="noreferrer">dpo@esa.int</a>.</li></ul><p>Once a request to erase data is received, we will ensure that the data are deleted unless it can be processed on another legal ground, as mentioned in Article 5.1 above. If Your data was processed for several purposes, We do not process personal data for the part of the processing for which consent has been withdrawn.</p><p>For instance:</p><ul><li>Your personal data may continue to be processed for the performance of a legal obligation of ESA or where such data is necessary for the establishment, exercise, or defence of legal claims;</li><li>If there are multiple processing concerning You, based on consent, You have to expressly indicate which consent you wish to withdraw.</li></ul><p>When the processing of Your personal data are based on Your consent and unless a specific case applies (e.g. see Article 6 above), You have also the right to withdraw Your consent.</p><p>You may wish to exercise any of the above-mentioned rights, by sending a request explicitly specifying Your query to the ESA DPO via e-mail at <a href="mailto:dpo@esa.int" class="link" target="_blank" rel="noreferrer">dpo@esa.int</a>. You may be asked additional information to confirm your identity and/or to assist ESA to locate the data You are seeking.</p><div class="large-space"></div>',63)])])}const f=o(i,[["render",n]]);export{h as __pageData,f as default};
